insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('sea-salt-paper','Sea Salt & Paper','Hold','Family','Family of 3','Couple (2P)',82,'Card / push-your-luck','2-4 (best 2)','8+','30-45','1.5','7.51','$15-20','Origami-themed card game of set collection with a push-your-luck round-ending call: stop now, or dare a last round and risk handing over the points.','Not sold on it. Not sure where the excitement come in','NEW SUGGESTION. Fast, gorgeous, and the round-ending ''STOP or LAST CHANCE'' call creates real tension in a 30-minute box. 7.51 with 23k+ ratings, #253. Snappy turns keep your son engaged, and it is genuinely brilliant at 2 for you and your wife.','367220','https://cf.geekdo-images.com/CIh_rXKoRw9z8K0PJxT8nQ__previewthumb/img/L2S5Hio-50FTnWQWZPeX3aeDAME=/fit-in/300x320/filters:strip_icc()/pic6973911.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
