insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('ticket-to-ride-europe-or-legacy','Ticket to Ride (Europe or Legacy)','Buy','Family','Family of 3',NULL,80,'Route building (+legacy option)','2-5 (best 4)','8+ (Legacy 10+)','30-60 (Legacy 20-90)','1.9 / 2.6','7.52 / 8.62','$45 / $90-110','Collect train cards to claim routes. Europe = evergreen standalone; Legacy: Legends of the West = 12-game campaign whose custom map stays fully replayable afterward.','I think so, just not sure which version','Per our chat you are leaning Legacy, and the data backs it: 8.62, #50 overall, the best-reviewed family-weight legacy game made, and nothing gets destroyed - you keep a playable custom USA map after the 12 sessions. Europe (7.52, ~$45) is the cheaper play-tonight option. Legacy lands best once your son is ~9-10, and it is a Days of Wonder evergreen - zero rush. Link goes to the Legacy page.','390092','https://cf.geekdo-images.com/2H0pJddVJA3r6btqRNLG1g__previewthumb/img/cEgblMZyfrlkzQRlurTWd1bF9oA=/fit-in/300x320/filters:strip_icc()/pic7541330.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
