insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('long-shot-the-dice-game','Long Shot: The Dice Game','Hold','Family','Beach - Mixed Ages','Family of 3',79,'Roll-and-write / betting','1-8 (best 4-5)','14+','25','2.0','7.51','$30-35','Everyone bets on and shares the same horse race, marking their own sheet.','Competes with Camel Up and Ready Set Bet, but just does not feel as fun as Camel Up for the extra work in the game','Everyone acts on every roll of the shared dice - the no-downtime pattern again - and it is the gamiest of the racing trio at weight 2.0. Ready Set Bet is louder and more communal; this one gives the adults more decisions. 7.51, #369.','295374','https://cf.geekdo-images.com/j9RO81ihYw0_oPj6iqV_bA__previewthumb/img/1I-e5LBFcb8SKN9Wt5IVYUghKxI=/fit-in/300x320/filters:strip_icc()/pic6682376.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('king-of-tokyo','King of Tokyo','Buy','Family','Family of 3','Beach - Mixed Ages',78,'Dice combat','2-6 (best 4-5)','8+','30','1.5','7.11','$35-40','Giant monsters roll dice to smash each other and hold Tokyo.','-','Dice-chucking monster fights with almost no rules overhead. Your son wins on merit, adults still care, and it holds a top-500 rank a decade on. Also earns its keep with the beach crowd at 5-6 players.','70323','https://cf.geekdo-images.com/m_RzXpHURC0_xLkvRSR_sw__previewthumb/img/QSlVpVg11D4_b8uXcADhP8iSoYc=/fit-in/300x320/filters:strip_icc()/pic3043734.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('ice-cool','Ice Cool','Buy','Family','Beach - Everyone','Kids 6-8',78,'Dexterity','2-4 (best 4)','6+','30','1.1','6.78','$30-35','Flick weighted penguins through doorways in a nested box school.','Looks fun, if a bit silly, but that could be great','Flicking penguins draws a crowd of spectators, 6+ works for real, and the physics equalize adult vs kid skill. The one honest knock: it is a bulky box for a packed beach car.','177524','https://cf.geekdo-images.com/xVx8ex1fjO9C7W8rRvWdVQ__previewthumb/img/HtdCK_sG-AST0J_Zgk4A8hCjU0Y=/fit-in/300x320/filters:strip_icc()/pic3320017.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('flip-7','Flip 7','Own','Family','Beach - Mixed Ages','Family of 3',78,'Push-your-luck cards','3-18 (best 5-6)','8+','20','1.0','7.22','$10-14','Keep flipping cards for points until you bust.','Always a good time but lost some luster - could just be that we have not played recently.','The community caught up to your read: 7.22 with 24k ratings, and the poll confirms it peaks at 5-6. It is a crowd filler, not a trio game - it will revive hard at the beach, where it scales to 18.','420087','https://cf.geekdo-images.com/YrQxEB9Ef0kQorRApzG5vQ__previewthumb/img/Uz6XJlsaVYPaz3_4NFYr_C9yzVk=/fit-in/300x320/filters:strip_icc()/pic8780246.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('survive-the-island-2024-ed','Survive The Island (2024 ed.)','Buy','Family','Beach - Mixed Ages','Family of 3',78,'Take-that / area movement','2-5 (best 4)','8+','45','1.5','7.44','$30-35','The island is sinking - get your meeples to safety while sharks and kaiju eat everyone else''s. 2024 refresh of the 1982 classic.','Will Buy with the expansion. May just end up for the kids, but we''ll see','Buy the 2024 edition (the one on Amazon): base box now seats 2-5 so no expansion needed, it is lighter (1.5), brighter, rated above the classic (7.44 vs 7.31), and the community plays it from age 6. Score bumped 74 -> 78 accordingly. Only caveat: it caps at 5 players - the old edition plus its mini-expansion was the only road to 6. The 2025 Monster Pack (~$15, new monster types, no player-count change) is the earned-it-next-summer upgrade.','425428','https://cf.geekdo-images.com/MG8gloAo6F2cD4C6gz12Lg__previewthumb/img/-fnTHBdc7BCUomRA0bWnxvC-7UQ=/fit-in/300x320/filters:strip_icc()/pic8337555.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('magic-maze','Magic Maze','Buy','Family','Family of 3','Beach - Mixed Ages',74,'Real-time co-op','1-8 (best 4)','8+','15','1.8','6.93','$25-35','Real-time co-op where all players simultaneously move the SAME pawns - and no one is allowed to speak.','Must buy, expansion could be bought if this gets play like I think it will','NEW SUGGESTION, with a caveat. You cannot alpha-player a game where talking is forbidden - the table communicates by slamming a big red pawn and staring meaningfully. Kids find the enforced silence hilarious. Caveat: some tables find the time pressure stressful, hence Research not Buy.','209778','https://cf.geekdo-images.com/NVsxRYyE_vIBzObK72maCQ__previewthumb/img/xglfCYsuuAdCSFVQNWlG1QSPc8o=/fit-in/300x320/filters:strip_icc()/pic9402780.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('size-wise','Size Wise','Buy','Family','Beach - Mixed Ages','Beach - Adults',73,'Party / estimation','3-8 (best 4-5)','6+','15-25','1.3','8.24 (32v)','$25-30 preorder','Estimate and rank the sizes of things - there is no right answer, only matching the room.','So simple could be hilarious.','It ships this month (July 2026), so the 8.24 is 32 preorder-hype votes - treat it as unrated. The pitch (tactile estimation, 3-8 players, age 6+, 20 minutes) is a legitimately good porch fit. Wait for real reviews, then decide fast if they land.','457019','https://cf.geekdo-images.com/HzpcSdPkYdYvujz137VspA__previewthumb/img/N5_2Sfoo8QYXdzEinsNgnv70OX0=/fit-in/300x320/filters:strip_icc()/pic9496662.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('pandemic','Pandemic','Own','Family','Family of 3',NULL,72,'Co-op','2-4 (best 4)','8+','45','2.4','7.51','$35-45','Team up to stop four diseases from going global.','We enjoy it but one person ends up telling everyone else what to do so they are just there for the journey.','Your alpha-player diagnosis is structurally correct: fully open information means the strongest player can always compute everyone''s best move. Fine game, known flaw, not fixable by house rule.','30549','https://cf.geekdo-images.com/S3ybV1LAp-8SnHIXLLjVqA__previewthumb/img/89tAMBmsLsaHj5LKFmyXWxQxiZs=/fit-in/300x320/filters:strip_icc()/pic1534148.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('betrayal-at-house-on-the-hill-3rd-ed','Betrayal at House on the Hill (3rd ed.)','Hold','Family','Beach - Mixed Ages','Family of 3',72,'Exploration / hidden traitor','3-6 (best 5)','12+','60','2.4','7.29','$35-50','Explore a haunted house until someone turns traitor and it becomes everyone-vs-one.','Looks kind of cool, but I''m hearing there are some downsides with presentation of book and confusion in wording which really can through me off','The poll says best at exactly 5 and it is properly spooky at 12+ - so this is a beach-evening game for adults plus the older kids, not a table-of-3 game. Great fun if everyone expects a chaotic story generator rather than a balanced contest.','358504','https://cf.geekdo-images.com/nLDGtbwdSC0eYKffjYzrnQ__previewthumb/img/Chiu1mqey1pFuTGrxPWReB4XaiM=/fit-in/300x320/filters:strip_icc()/pic6917219.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('familiar-tales','Familiar Tales','Hold','Family','Family of 3','Campaign - Couple',71,'Co-op storybook campaign','1-4 (best 4)','8+','45-120','2.5','7.65','$40-60','Storybook adventure campaign where your heroes level up across chapters.','Looks like it is more complicated than Stuffed Fables which concerns me, will do more research and hold for now','Cleaner ruleset than Stuffed Fables from the same designer, a real campaign arc, and a solid 7.65. But it is still strict turn order, so the downtime issue rides along with it. Your ''needs to learn turns'' framing is the right lens - it is a training ground, not a fix.','350948','https://cf.geekdo-images.com/Rr2tK2caPxzFLRvMbrf4sQ__previewthumb/img/qB8XMSXuh8NfH2A37I-mriQQ9vw=/fit-in/300x320/filters:strip_icc()/pic6499900.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('castle-panic','Castle Panic','Own','Family','Family of 3',NULL,70,'Co-op tower defense','1-6 (best 4)','8+','30-60','1.7','6.65','$35-40','Trade cards and coordinate to stop monsters reaching your castle.','Really like it but again it can be prescriptive if one player is super strategic (me).','Try hidden hands plus a no-naming-cards rule - it converts a solvable puzzle into actual tension, and it costs nothing. The most fixable co-op you own.','43443','https://cf.geekdo-images.com/ryPiCH15spkrdtvUI-utuA__previewthumb/img/kfMlRqMHCwvIpzhbz04EnUFNNLQ=/fit-in/300x320/filters:strip_icc()/pic6966125.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('so-clover','So Clover','Pass','Family','Beach - Mixed Ages','Family of 3',70,'Co-op word association','3-6 (best 3-4)','10+','30','1.1','7.59','$20-25','Write clues linking word pairs on a clover then the group reconstructs your board.','Nope.','For the record: simultaneous secret clue-writing, alpha-proof by design, and a strong 7.59 at #269. But your ''Nope'' reads like the word-association genre itself is the issue, and no rating fixes taste. Scored on merit; vetoed on preference is legitimate.','329839','https://cf.geekdo-images.com/8oipK9-ivkn53h7L5U2Yfg__previewthumb/img/2-erhAHY-4SQYaLHSikQxCDdG80=/fit-in/300x320/filters:strip_icc()/pic6588069.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('stuffed-fables','Stuffed Fables','Own','Family','Family of 3','Kids 6-8',68,'Co-op story adventure','2-4 (best 4)','7+','60-90','2.5','7.40','$55-70','Adventure played across the pages of a giant storybook.','We like it but my son gets distracted waiting for his turn. The rules layout leaves us confused about what to do or where to go.','Live weight is 2.46 - noticeably heavier than the storybook look implies, which is exactly your rules-confusion complaint. The fan-made reference sheets on BGG genuinely fix half of it. The turn-order downtime is baked in.','233312','https://cf.geekdo-images.com/CS83e1WOA5WMc4izRw6zwg__previewthumb/img/m7iKuNy6gwSMKrAHDswpnrfO-SE=/fit-in/300x320/filters:strip_icc()/pic3708878.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('six-sojourns','Six Sojourns','Pass','Family','Family of 3',NULL,66,'Area control / linked campaign','2-4 (best 3-4)','8+','30-60','2.2','7.37 (165v)','$30-40','Six short area-control games that can be played in sequence as a campaign.','Looks real repetitive.','A year after release it has only 165 ratings (7.37) - it never found an audience, so real-world reviews are thin. The linked-games idea is genuinely neat, but this is an unproven bet, not a find. Low priority.','439826','https://cf.geekdo-images.com/6ESAEzGPQQ-IhTsKrcm8Nw__previewthumb/img/IQ-NSLe0h3kxiEHDjd7d5j998mg=/fit-in/300x320/filters:strip_icc()/pic8725884.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('wildblooms','Wildblooms','Pass','Family','Family of 3',NULL,55,'Card / tableau','2-5 (best 2-3)','10+','30','1.9','5.98 (80v)','$25-30','Nature-themed card game where you take an action on every turn including other players'' turns.','Meh.','MOVED BACK from Buy. The act-on-every-turn hook is real, but the live community verdict is a 5.98 - well below average - with reviewers calling the actual decisions thin. Your one-word review beat the previous researcher''s theory. Only revisit if you can try it before buying.','446878','https://cf.geekdo-images.com/ZgDp4SGl2QmOTwEdT7E4yA__previewthumb/img/rnHCaX2_Qo18T2ndUb6iFWVOHuQ=/fit-in/300x320/filters:strip_icc()/pic9334946.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('zombie-kidz-evolution','Zombie Kidz Evolution','Own','Kids','Kids 6-8','Family of 3',88,'Co-op legacy','2-4 (best 3-4)','7+','15','1.4','7.56','$20-25','Kids defend a school from zombies unlocking new rules over 12 games.','Really enjoy it - quick setup quick play. Recently beat Wild Wild Taco in our tournament.','The best thing you own for this age group, per the data: 7.56 at #574 is elite for a kids'' game. Legacy envelopes keep them coming back, and 15-minute rounds mean the alpha issue barely has time to matter. Kids can run it unsupervised at the beach.','256952','https://cf.geekdo-images.com/Iwv0Vg8FXIKlEr8xKsapIQ__previewthumb/img/oVpl71VwnZAiK3w1M88fLiGn_fQ=/fit-in/300x320/filters:strip_icc()/pic4334067.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
