insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('cosy-stickerville','Cosy Stickerville','Buy','Kids','Kids 6-8','Little Kids 4-5',80,'Sticker flip-and-write','1-6 (best 2)','8+','30','1.2','8.25','$20-25','Place stickers to build out a town.','Want to buy. Maybe for the middle girls to play down the beach. Cheap enough that I don''t care if it gets used up.','Your instinct checks out hard: live rating 8.25 at #735 and climbing - a breakout 2026 hit. It is ''Cozy Stickerville'', 1-6 players, and yes it is consumable by design: check refill-pack availability, though at ~$25 replacing the whole box is painless.','456440','https://cf.geekdo-images.com/tQn8UU3A_zsi730zNQyNzA__previewthumb/img/_SMA94BEdgRZFmW4vl_3HuQvX3U=/fit-in/300x320/filters:strip_icc()/pic9171780.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
