insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('rat-a-tat-cat','Rat-a-Tat Cat','Buy','Kids','Kids 6-8',NULL,72,'Memory / card','2-6 (best 4)','6+','10','1.1','6.26','$10-12','Remember your own hidden cards and swap for lower ones.','Looks good, I think there was a drinking game in college like this, Golf, maybe','A Mensa-award memory game kids run entirely alone, for $10, that quietly teaches probability. The 6.26 is adults grading a teaching tool - for its job it is excellent.','3837','https://cf.geekdo-images.com/4nQQ9GA-1JXcxwNd-tCR8w__previewthumb/img/mibk3fa_5JSZTTN5bDZB_QceT24=/fit-in/300x320/filters:strip_icc()/pic147435.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('catapult-feud','Catapult Feud','Hold','Kids','Kids 6-8',NULL,68,'Dexterity','2 only','7+','20-30','1.1','6.98','$35-45','Flick projectiles from catapults to knock down the other player''s castle.','Still think magnatiles and magnet cubes could replace their cheap looking blocks','Correction: base game is exactly 2 players, not 2-4 - that changes its beach math to a head-to-head duel with spectators. Your thin-content instinct is right; the official expansions (Vikings, Volcano, Siege) are the intended fix, not magnet tiles, which will not survive contact with the flicking physics.','310789','https://cf.geekdo-images.com/xGBfcwwpk6qW4FfPryGbBQ__previewthumb/img/69mknIPgN2Q4qvNqD7fvEyOQgYo=/fit-in/300x320/filters:strip_icc()/pic8365828.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
