insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('wavelength','Wavelength','Pass','Adults','Beach - Adults','Beach - Mixed Ages',90,'Team guessing / party','2-12 (best 6-8)','14+','30-45','1.1','7.19','$25-30','Your team guesses where your clue falls on a spectrum between two extremes.','Only because you have to think of the things yourself','Still the adult-evening pick: teaches in two minutes, scales to 12, and it manufactures exactly the kind of arguing that bonds five families. Box says 14+ but the community plays it from 10, so older kids can join teams.','262543','https://cf.geekdo-images.com/z4fbPdmJg_5yphJEvql4ZA__previewthumb/img/lpGQJSaLEF1wj1ytCzg-IMgUcp4=/fit-in/300x320/filters:strip_icc()/pic4552862.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('sky-team','Sky Team','Hold','Adults','Couple (2P)',NULL,88,'Co-op dice placement (2P only)','2 only','10+','20','2.0','8.12','$25-30','You are pilot and co-pilot landing an airplane together, placing hidden dice with strictly limited communication.','heard great things in reviews, but just can not get into it','NEW SUGGESTION and the best two-player box of the last several years: 8.12, #32 overall, Kennerspiel des Jahres winner, 20 minutes, ~$27. Communication limits mean neither of you can pilot the other - the anti-alpha design applied to a couple. An easy first-order.','373106','https://cf.geekdo-images.com/uXMeQzNenHb3zK7Hoa6b2w__previewthumb/img/cnpnOSqkt_k2qk19EoudZjKOom0=/fit-in/300x320/filters:strip_icc()/pic7398904.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('monikers','Monikers','Hold','Adults','Beach - Adults',NULL,82,'Party / charades','4-16 (best 6-10)','17+','30-60','1.1','7.75','$25-30','Same cards three rounds - describe freely then one word then charades.','Sounds hilarious, just not right now','7.75 and the funniest game on this sheet with the right crowd - but the base deck earns its 17+ rating. Strictly an after-bedtime game. If the kids-asleep window at the beach is real, promote this to Buy on the spot.','156546','https://cf.geekdo-images.com/XvWGuvDebUB5Vht9x00ZMg__previewthumb/img/Ff_j8xo_40ox4RUNoDq5PxsiNNk=/fit-in/300x320/filters:strip_icc()/pic9147640.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('zenith','Zenith','Buy','Adults','Couple (2P)',NULL,82,'2P card duel (tug-of-war)','2-4 (best 2)','12+','25-35','2.3','7.97','$35-40','Card duel over five planets: play one card per turn to influence a planet, climb a tech track, or take leadership.','Looks like a lot to manage, but it all appears to be connected so maybe not as hard as the setup video makes it seam','The live data firmly backs the reversal of your first take: 7.97 at #552, one card per turn, 25-35 minutes - low effort, real depth. The 4-player mode is a 2v2 afterthought, so buy it as a you-and-wife duel or not at all. Expect one game of icon-checking, then it flies.','424219','https://cf.geekdo-images.com/NvE9BcCiYXhYT2iV61C6kA__previewthumb/img/WU7xQZTlmNYLuQuyEC3nyKKmbqA=/fit-in/300x320/filters:strip_icc()/pic8855575.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('hot-streak','Hot Streak','Own','Adults','Beach - Adults',NULL,80,'Party / list-making','2-8 (best 5-6)','6+','20','1.2','7.81','$20-25','Fast-paced category and list party game.','I like it and think it would be more fun with more people if they are competitive and rooting more than just my family does.','Live data vindicates you harder than expected: 7.81 at rank #315 - this 2025 release is a legitimate hit, and it is built for exactly the loud competitive crowd you described. Bring it to the beach; it was made for that room.','446497','https://cf.geekdo-images.com/co36SqyPYlM1QwVW6XSwyQ__previewthumb/img/oPsaGdysFdNE5wVPut_Y4AJfhU4=/fit-in/300x320/filters:strip_icc()/pic8933083.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('toy-battle','Toy Battle','Buy','Adults','Couple (2P)','Kids 6-8',80,'2P area majority','2 only','8+','15','1.5','7.83','$20-25','Send toy armies to conquer territories in a 15-minute head-to-head - Paolo Mori design, one of 2025''s biggest small games.',NULL,'Easy call: 7.83 at #316 overall, 15 minutes, ~$25, in print - and age 8+ means it doubles as a you-vs-son duel, not just a couples game. The only one of the four new adds I would order today. An expansion (La Croisette) exists if it lands.','434654','https://cf.geekdo-images.com/GuhpuTKFteZEIhPTFvEpJw__previewthumb/img/7q5Vv5tU8si9v3ueQRHXpOM5OgA=/fit-in/300x320/filters:strip_icc()/pic8589750.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('agent-ave','Agent Ave','Buy','Adults','Couple (2P)','Kids 6-8',78,'2P deduction race','2-4 (best 2)','8+','10-20','1.2','7.52','$20-25','Light spy-themed deduction race. Correct title: Agent Avenue (2024).','Looks super simple and fun will buy.','Found it: ''Agent Avenue'', 7.52 at #532 - a legit sleeper hit. The verify-player-count concern was warranted: the poll says best at exactly 2 (four players is a 2v2 team variant). Think you-vs-son or you-vs-wife quick duels, not a group game. Still a good buy at that framing.','422732','https://cf.geekdo-images.com/qC5YwZANir1Cmg6d-1UUpQ__previewthumb/img/Zv-RqPkePVL7AXm2-FUKMGk9Amw=/fit-in/300x320/filters:strip_icc()/pic8427963.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('lairs','Lairs','Hold','Adults','Couple (2P)',NULL,78,'Dungeon-builder duel','2 only','10+','30-60','2.3','8.13 (555v)','$50-60 (KS)','Build a devious dungeon, then explore your rival''s creation - a 2-player duel of trap-setting and tomb-raiding.','Get more reviews on this for longevity','The strongest of your four new finds for the card-battle-with-wife hunt: 8.13 from 555 early owners, 2-player only, and real build-then-invade asymmetry. Caveat: it is a Kickstarter-first 2026 release - confirm retail availability before falling in love. If it hits shelves at a sane price, this challenges Zenith for that slot.','404883','https://cf.geekdo-images.com/6ckw7g0al43ARdYWcwY5uQ__previewthumb/img/heHtTKRCpzrikGgMo0OupwMJbj4=/fit-in/300x320/filters:strip_icc()/pic9627746.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('skull','Skull','Pass','Adults','Beach - Adults',NULL,76,'Bluffing','3-6 (best 5-6)','10+','15-45','1.1','7.17','$15-20','Bet on how many flowers you can flip without hitting a skull.','Passed on this one just really nothing to it that I can see.','Note this Pass outscores some Buys - that is the flag system working. Four cards per player IS the whole game, but what it does with them is a modern-classic bluffing design (7.17, beloved for 15 years). If your group ever wants pure psychology over activity, re-look. Capped at 6, which is its real limit for you.','92415','https://cf.geekdo-images.com/GVbKORueiHezUaLfVZKlfQ__previewthumb/img/TI7AyxZ7g2v_PWgBj7LJk3us7mE=/fit-in/300x320/filters:strip_icc()/pic9315848.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('wizard-s-grimoire','Wizard''s Grimoire','Hold','Adults','Couple (2P)',NULL,76,'2P spell duel','2 only','10+','20-40','2.1','7.41 (880v)','$35-40','Spell-casting card duel. Correct title: Wizards of the Grimoire (2022).','Will keep comparing to Zenith, but I am looking for a card battle type game','Confirmed 2-player only, so it lives in the you-and-wife slot. 7.41 with a clever spell-cooldown system that creates real timing decisions. Solid - but if you are buying one duel this year, Zenith and Sky Team both outscore it here.','340541','https://cf.geekdo-images.com/QqRJNlp7875oPeRp10fDxQ__previewthumb/img/j7L32Gm5mbLOoJzdB7Go7Vsf7c8=/fit-in/300x320/filters:strip_icc()/pic7013765.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('wroth','Wroth','Buy','Adults','Couple (2P)',NULL,72,'Area control / dice drafting','1-4 (best 4)','13+','60','2.3','7.49','$55-65 ($64.95 MSRP)','Draft action dice to gain resources deploy troops and fight for control of the island. Five asymmetric factions. PvP co-op or solo.','Want it just need to find it.','Your call overrides my demotion and it is your table - noted and respected. Keeping the caveats on record: the live rating is 7.49 (the 8.03 was launch hype) and the community poll says best at 4 players, so at 2 you would be playing its weakest count. Watch one 2-player playthrough before the $60 leaves your wallet and I am at peace.','414117','https://cf.geekdo-images.com/pF07bElBCzBj1en-zTwFtQ__previewthumb/img/zqMBTMFjNdtcaNe84Vp5zGx9e_0=/fit-in/300x320/filters:strip_icc()/pic8978903.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('sleeping-gods-or-distant-skies','Sleeping Gods (or Distant Skies)','Research','Heavy','Campaign - Couple',NULL,90,'Open-world story campaign','1-4 (best 1-2)','13+','60-120 /session','3.0','8.29 (DS) / 8.08','$60-90','You captain a ship lost in a strange sea exploring an atlas to find your way home.','Will take a closer look, Have looked at Sleeping Gods a lot, and it looks like a lot to track, but will look at Distant Skies','Top campaign pick, now sharpened by data: get DISTANT SKIES specifically - 8.29 vs 8.08, cleaner rulebook, standalone, and the poll says best at exactly 1-2 players. ''Get home'' is the purpose Jaws of the Lion lacked, and it saves in five minutes for 90-minute evenings.','358320','https://cf.geekdo-images.com/r72BZoC3whophBzKi45Rgg__previewthumb/img/Na6jm9fcPnsFojxkAZ8lgzt5MRU=/fit-in/300x320/filters:strip_icc()/pic6737677.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('pandemic-legacy-season-1','Pandemic Legacy: Season 1','Buy','Heavy','Campaign - Couple',NULL,86,'Co-op legacy campaign','2-4 (best 4)','13+','60','2.8','8.50','$50-70','Pandemic over 12-24 linked games with permanent consequences and an escalating story.','Will buy','MOVED Research -> Buy. It is the #3 ranked game of all time (8.50), you already know base Pandemic cold so the learning cost is zero, and at 2 players the alpha problem mostly dissolves into conversation with your wife. Permanent consequences give the base game the stakes it was missing. The safest great campaign money can buy.','161936','https://cf.geekdo-images.com/-Qer2BBPG7qGGDu6KcVDIw__previewthumb/img/MN0rRmlJ-lNPkR8cpBjJy-vSLSA=/fit-in/300x320/filters:strip_icc()/pic2452831.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('lands-of-evershade','Lands of Evershade','Backed','Heavy','Campaign - Couple',NULL,84,'Hybrid RPG / tactical campaign','1-5 (best 2-3)','14+','90-270 /chapter','3.3','8.85 (590v)','Already pledged','Awaken Realms hybrid RPG/board game - D12 skill checks fast tactical combat grimdark fantasy campaign books.','Already backed the second round.','Early live numbers back your pledge: 8.85 from ~600 wave-1 backers (inflated, but directionally strong), weight 3.3. Real planning note: chapters run 90 to 270 minutes, so this needs protected evenings, not weeknight scraps. Incoming, not a decision - and a good-looking incoming.','415848','https://cf.geekdo-images.com/y1OVwSAaHP-pFpYEJ9r5Zg__previewthumb/img/t2BeRDoL4nFREeZyf1Um_KahLbA=/fit-in/300x320/filters:strip_icc()/pic8061460.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('clank-legacy-acquisitions-incorporated','Clank! Legacy: Acquisitions Incorporated','Buy','Heavy','Campaign - Couple',NULL,82,'Competitive legacy deckbuilder','2-4 (best 4)','13+','90-120','2.7','8.49','$70-90','A corporate-dungeon-delving comedy campaign where you permanently mark up the board.','Was looking at this one, thanks for reminding me','8.49 at #28, and still the funniest campaign writing in the hobby. Competitive, so quarterbacking is structurally impossible. Plays fine at 2; sings at 3-4 if another couple from the beach crew ever joins a run.','266507','https://cf.geekdo-images.com/hc2NDafu5c24iLJh_IZmyg__previewthumb/img/lduYEpi5ud7co2hN9ULnZulZSfk=/fit-in/300x320/filters:strip_icc()/pic4885780.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('oathsworn-into-the-deepwood','Oathsworn: Into the Deepwood','Buy','Heavy','Campaign - Couple',NULL,80,'Story-heavy tactical campaign','1-4 (best 2 or 4)','14+','30-90 x2 /chapter','3.7','8.76','$150-180','A huge branching narrative campaign with deep tactical boss fights.','We weighted this against Jaws of the Lion when we were looking for a big game and think we may switch to this for the story.','8.76 at #63: the best boss fights in cardboard plus genuinely great narration (there is a free companion app that reads the story aloud). The cost is real - big setup, big table, $150+. If story-hunger ever decisively beats setup-tolerance, this is the ceiling of that trade.','251661','https://cf.geekdo-images.com/dezQ4YjF03lZVxTdI-UJYw__previewthumb/img/BR1JdfuqCdULEXpiy5YH0-nR8NQ=/fit-in/300x320/filters:strip_icc()/pic6863204.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('arydia-the-paths-we-dare-tread','Arydia: The Paths We Dare Tread','Hold','Heavy','Campaign - Couple',NULL,76,'Open-world co-op RPG campaign','1-4 (best 2)','14+','60-240 /session','3.3','8.98','2nd printing TBA','Open-world campaign RPG: 60+ pre-painted minis 900+ cards 300+ map cards 40+ hours of content.','Will hold on this one for next printing. I see mixed things on the story holding up through long term play','The 8.98 is backer-inflated but the design under it is real: open-world, pre-painted minis, and card-box storage that makes setup surprisingly fast for its size. Second printing still pending - get on the notification list and do not pay scalper prices in the meantime.','219650','https://cf.geekdo-images.com/GGXq2lRAJCtS1yPPPmdVKw__previewthumb/img/XSVjTILnJ59OEjesQ2AYDqzlHFM=/fit-in/300x320/filters:strip_icc()/pic6205610.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('lost-ruins-of-arnak','Lost Ruins of Arnak','Hold','Heavy','Couple (2P)',NULL,74,'Deckbuilder / worker placement','1-4 (best 3)','12+','30-120','2.9','8.08','$45-60','Explore an island build a deck and place workers to research a lost civilization.','Will take another look based on your recommendation','Here is the Pass-outranking-Buys signal you asked the scoring to surface: 8.08, #30 overall, plays beautifully at 2, and its reputation for heavy setup is overstated (one board, some decks). Of every Pass on this sheet, this is the one most worth a second date. If it still is not for you after that, close the book honestly.','312484','https://cf.geekdo-images.com/6GqH14TJJhza86BX5HCLEQ__previewthumb/img/LyqJjy96rRp9TheC2I5Yk1v8UYQ=/fit-in/300x320/filters:strip_icc()/pic5674958.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('destinies','Destinies','Pass','Heavy','Campaign - Couple',NULL,74,'App-driven story race','1-3 (best 2)','14+','90-150','1.9','7.64','$40-60','An app-run RPG where each player races to complete their own destiny.','The screen thing worries me, and it basically only being reading sounds a bit boring','The app carries every rule, so setup and upkeep are near zero, and it is competitive, so no alpha - both of your stated pains solved at once (7.64). The honest tradeoff: the scan-and-read loop IS the game, and you are on a screen all evening.','285192','https://cf.geekdo-images.com/oaD1ZQ3yGj6lacLdtqgdnQ__previewthumb/img/OrW8HC0vq9VrGtpJYNhNFJoWn-U=/fit-in/300x320/filters:strip_icc()/pic5558118.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('gloomhaven-jaws-of-the-lion','Gloomhaven: Jaws of the Lion','Own','Heavy','Campaign - Couple',NULL,70,'Tactical dungeon crawl','1-4 (best 2)','14+','30-120','3.6','8.35','$30-50','Scenario-based tactical combat with a hand-management card system.','Wife and I like it but it is hard to get into - setup and lots of rules to track. Companion app helps with the element stuff. Story is basically non-existent and we would like it heavier.','8.35 at #12 says the combat engine is world-class; your complaint is about what it is not (a story), and no expansion changes that - it is a tactics box with narrative wallpaper. Keep it for tactical nights and buy narrative elsewhere. Skip Frosthaven: it is more of everything you disliked.','291457','https://cf.geekdo-images.com/_HhIdavYW-hid20Iq3hhmg__previewthumb/img/i2lDgGf06UWZm0R34hkN0MMZo3s=/fit-in/300x320/filters:strip_icc()/pic5055631.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('rove','Rove','Research','Heavy','Couple (2P)','Campaign - Couple',69,'Exploration / survival','1-4 (best 2)','14+','60-120','3.5','8.04','$50-70','Explore the world of Chorus and fight for survival against nature itself. 2025 release.',NULL,'You flagged this one. Heavy for your table (weight 3.5, 60-120 min) and best at 2, so it sits in the couple/campaign slot. Strong early rating (8.04) but from only ~200 votes, so treat it as provisional. The exploration/survival interaction is appealing; the open question is tracking load - the exact axis you and I discussed, so preview a playthrough for how much live state it asks you to hold before buying.','365670','https://cf.geekdo-images.com/QtLIH1Hf2bA2Ix9b0vIGUA__previewthumb/img/0oYq1E_IDrsS6nNjzIdF8DK9muM=/fit-in/300x320/filters:strip_icc()/pic6978243.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('dwellings-of-eldervale','Dwellings of Eldervale','Research','Heavy','Couple (2P)','Beach - Adults',68,'Worker placement / area control hybrid','1-5 (best 3)','14+','60-150','3.2','8.10','$70-90','Fantasy worker placement fused with area control, dice combat, engine building and giant monster minis - workers get eaten by dragons.',NULL,'Strong pedigree: 8.10 at #129 from 9.6k raters. It has what Cascadia lacked for you - direct interaction, dice-fight luck, table drama - and the core turn is the good kind of simple (place one worker or recall all). The open question is tracking load: eight asymmetric factions, element tracks, spells and dwellings all run concurrently, Arnak-plus territory at 90+ minutes, and the poll says best at 3. Before buying, also look at Andromeda''s Edge (2024, 8.3) - the same designer''s space-refinement of this exact formula, and the one most fans now reach for first.','271055','https://cf.geekdo-images.com/qJQXn0kvzvHBKWzSQN7vpw__previewthumb/img/OxEW6rx5T83CmAD2R6-rFGQ84ng=/fit-in/300x320/filters:strip_icc()/pic4742944.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('avalon','Avalon: The Riven Veil','Buy','Heavy','Couple (2P)',NULL,66,'Area control / exploration','2-5 (best 3)','14+','60-120','3.3','8.28 (66v)','$100+ (KS)','Lead a faction across the mist-shrouded isle of Avalon in an Arthurian area-control game: explore hidden lands, claim legendary relics, bond mythic beasts, hunt the Grail, and fight for territory over two-to-three seasons.','Need more research but looks cool.','Not the party game Avalon - this is Shadowborne''s 2026 Kickstarter: a mid-heavy area-control minis game (weight ~3.25, best at 3, 1-2 hours). It leans on exploration, faction asymmetry, and table conflict, which fits your taste for interaction over solitaire-style building. Two honest cautions: it''s barely rated (8.28 from ~66 preorder votes, overall rank ~15,800), so the score is hope, not proof; and at this weight with lots of moving parts it''s a you-and-wife (or small-group) Heavy-night game, not a beach filler. Worth tracking - hold final judgment until real reviews land.','402276','https://cf.geekdo-images.com/rXGLkG-3OCyERQS9zuN_dA__previewthumb/img/LQYk078tvBY2e6ds2cGcXQaEDdM=/fit-in/300x320/filters:strip_icc()/pic8505782.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('nemesis','Nemesis','Hold','Heavy','Beach - Adults','Couple (2P)',64,'Semi-co-op sci-fi horror','1-5 (best 4-5)','12+','90-180','3.5','8.25','$90-120','Alien-infested ship survival: work together to get home while hiding personal objectives that may betray the crew.','Certainly not for the beach. Just no chance we get that kind of time and if we do the fun games will override the deep thinking games. Will research more on this vs campaign version','The full-box Nemesis (2018, Awaken Realms): 8.25 at #25 overall - a genuine masterpiece of tension, and hidden objectives make it structurally alpha-proof. The honest fit-check: weight 3.5 (Jaws of the Lion territory - your setup/rules-tracking complaint applies in full), 2-3 hours, best at 4-5 players - so it wants a committed adult table, not 2 players or a casual porch. If the beach crew has 4 gamers willing to give it a full evening, it is unforgettable; otherwise 20 Strong: Nemesis (next row) is the sane-sized way into this universe. Nemesis Legacy (campaign version) hits Gamefound Q4 2026 if the theme grabs you.','167355','https://cf.geekdo-images.com/4KSmlm59w0GwLIlgDnJDAQ__previewthumb/img/oPUBR6tj9MLyfF_52g8RjDx4wfs=/fit-in/300x320/filters:strip_icc()/pic8211747.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('old-king-s-crown','Old King''s Crown','Pass','Heavy','Couple (2P)',NULL,62,'Area control / card drafting','1-4 (best 3)','12+','60-120','3.7','8.06','$70-100','Asymmetric faction area control with a bluffing card system.','Too much set up.','Live weight is 3.69 - a full point heavier than your sheet believed, and the community age poll says 14+. Your setup complaint was the right instinct; the data adds ''and the whole game is heavier than advertised''. Pass holds comfortably.','357873','https://cf.geekdo-images.com/q3Qp4L-rU3VOW6fMAFUJnQ__previewthumb/img/IV4PE6QK4Kea6NPr3j-FagAq3U8=/fit-in/300x320/filters:strip_icc()/pic8937255.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('20-strong-nemesis','20 Strong Nemesis','Pass','Heavy','Couple (2P)',NULL,60,'Solo/co-op dice-chucker','1-3 (best 1)','13+','40-60','3.0','7.05 (6v)','$35-45 preorder','Nemesis (the alien-horror hit) condensed into Chip Theory''s pocket 20 Strong dice system - fight through an infested ship.','Not looking for a solo experience, yet. It I was it would be strong story','Correct title: ''20 Strong: Nemesis'' (2026). Know what you would be buying: the 20 Strong system is solo-first - the poll says best at exactly 1 - and this deck runs heavier (weight 3.0) than the rest of the series. As a pocket Nemesis for solo evenings it is appealing; as a couples game it is a stretch. Preorder with 6 votes, so no real reviews yet.','466594','https://cf.geekdo-images.com/v_VwKivk4mRGKZBd49fgEg__previewthumb/img/t7sqSaQqn7Et46mkMkfX9AI5dvE=/fit-in/300x320/filters:strip_icc()/pic9677688.jpg',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
insert into public.games (id,name,status,category,best_for,also,score,type,players,ages,time,weight,bgg,price,what,notes,take,bgg_id,image,travel) values ('darwin-s-journey','Darwin''s Journey','Pass','Heavy','Couple (2P)',NULL,52,'Heavy euro / worker placement','1-4 (best 3)','14+','60-120','3.9','8.09','$55-70','Worker placement where your workers must be educated before they can act.','Too much for too little reward.','8.09 and beautifully engineered - for a table that is not yours. Weight 3.90 makes it the heaviest thing on this sheet. Your six-word review was exactly correct. Cleanest pass here.','322289','https://cf.geekdo-images.com/-A_ABjMw4PdoAZrH-FjiiA__previewthumb/img/8e_q4ButjcXSlugdNVGFGC79iw4=/fit-in/300x320/filters:strip_icc()/pic5726930.png',false) on conflict (id) do update set name=excluded.name,status=excluded.status,category=excluded.category,best_for=excluded.best_for,also=excluded.also,score=excluded.score,type=excluded.type,players=excluded.players,ages=excluded.ages,time=excluded.time,weight=excluded.weight,bgg=excluded.bgg,price=excluded.price,what=excluded.what,notes=excluded.notes,take=excluded.take,bgg_id=excluded.bgg_id,image=excluded.image;
