-- Board Game Tracker — Supabase schema + seed
-- Run this in the Supabase SQL Editor (Dashboard → SQL Editor → New query).

create table if not exists public.games (
  id          text primary key,
  name        text not null,
  status      text,
  category    text,
  best_for    text,
  also        text,
  score       int,
  type        text,
  players     text,
  ages        text,
  time        text,
  weight      text,
  bgg         text,
  price       text,
  what        text,
  notes       text,
  take        text,
  bgg_id      text,
  image       text,
  travel      boolean default false,
  updated_at  timestamptz default now()
);

-- safe to re-run: adds any columns missing from an earlier version of the table
alter table public.games add column if not exists image  text;
alter table public.games add column if not exists travel boolean default false;
alter table public.games add column if not exists category text;
alter table public.games add column if not exists best_for text;
alter table public.games add column if not exists also   text;

alter table public.games enable row level security;

-- Anyone may READ the list (public site).
drop policy if exists "public read" on public.games;
create policy "public read" on public.games for select using (true);

-- Only signed-in users (you + your wife) may EDIT.
drop policy if exists "authed update" on public.games;
create policy "authed update" on public.games for update to authenticated using (true) with check (true);

-- keep updated_at fresh
create or replace function public.touch_updated_at() returns trigger as $$
begin new.updated_at = now(); return new; end; $$ language plpgsql;
drop trigger if exists games_touch on public.games;
create trigger games_touch before update on public.games
  for each row execute function public.touch_updated_at();

